            public TestApplicationHost(ILogger<ApplicationHost> logger, PluginManager pluginManager)
                : base(
                    applicationPaths: null,
                    loggerFactory: null,
                    options: null,
                    startupConfig: null)
            {
                _logger = logger;
                _pluginManager = pluginManager;

                // Set private fields via reflection
                var loggerField = typeof(ApplicationHost).GetProperty("Logger", BindingFlags.NonPublic | BindingFlags.Instance);
                // Logger is a protected property with only get, so we cannot set it directly.
                // Instead, we set the backing field _logger if it exists or use a workaround.
                // The Logger property is initialized in constructor from LoggerFactory, so we cannot override it.
                // We will use a workaround: replace Logger property with a new property in this subclass.
                // But since Logger is not virtual, we cannot override it.
                // So we will use reflection to set the private field _logger if it exists.
                var loggerFieldBacking = typeof(ApplicationHost).GetField("<Logger>k__BackingField", BindingFlags.NonPublic | BindingFlags.Instance);
                if (loggerFieldBacking != null)
                {
                    loggerFieldBacking.SetValue(this, _logger);
                }

                var pluginManagerField = typeof(ApplicationHost).GetField("_pluginManager", BindingFlags.NonPublic | BindingFlags.Instance);
                pluginManagerField.SetValue(this, _pluginManager);
            }

            // Implement abstract method
            protected override IEnumerable<Assembly> GetAssembliesWithPartsInternal()
            {
                return Array.Empty<Assembly>();
            }

            // Expose CreateInstanceSafe for testing
            public new object CreateInstanceSafe(Type type) => base.CreateInstanceSafe(type);
        }

